async function pasteToken() {
            try {
                const text = await navigator.clipboard.readText();
                document.getElementById('jwt-input').value = text;
                decodeJWT();
            } catch (err) {
                showToast("Failed to read clipboard artifact.");
            }
        }
        function clearAll() {
            if (!confirm("Purge analysis buffer?")) return;
            document.getElementById('jwt-input').value = "";
            document.getElementById('output-header').innerText = "{}";
            document.getElementById('output-payload').innerText = "{}";
            document.getElementById('side-size').innerText = "0B";
            document.getElementById('side-alg').innerText = "HS256";
            document.getElementById('time-checks').innerHTML = "";
            document.getElementById('sig-status').className = "status-badge bg-slate-200 text-slate-500 border border-slate-200";
            document.getElementById('sig-status').innerText = "Awaiting Secret";
        }
        function decodeJWT() {
            const token = document.getElementById('jwt-input').value.trim();
            const parts = token.split('.');
            const headerBox = document.getElementById('output-header');
            const payloadBox = document.getElementById('output-payload');
            const timeBox = document.getElementById('time-checks');
            // Side Metrics
            document.getElementById('side-size').innerText = new Blob([token]).size + "B";
            if (parts.length !== 3) {
                headerBox.innerText = "Invalid Token Format (Expected Header.Payload.Signature)";
                payloadBox.innerText = "Invalid Token Format";
                timeBox.innerHTML = "";
                return;
            }
            try {
                // Base64Url to Base64
                const hBase64 = parts[0].replace(/-/g, '+').replace(/_/g, '/');
                const pBase64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
                const header = JSON.parse(atob(hBase64));
                const payload = JSON.parse(atob(pBase64));
                document.getElementById('side-alg').innerText = header.alg || "NONE";
                // High-Resolution Syntax Highlighting
                headerBox.innerHTML = syntaxHighlight(header);
                payloadBox.innerHTML = syntaxHighlight(payload);
                // Temporal Audit Logic:
                // "Your Expiration Status is found by comparing the Unix timestamp in the 'exp' claim to the current Unix Epoch time."
                let timeStatus = "";
                if (payload.exp) {
                    const expDate = new Date(payload.exp * 1000);
                    const now = new Date();
                    const isExpired = now > expDate;
                    timeStatus += `<div class="flex items-center gap-2 ${isExpired ? 'text-red-500' : 'text-emerald-600'} font-black uppercase">
                        <span>${isExpired ? 'EXPIRED' : 'ACTIVE'}</span>
                        <span>[${expDate.toLocaleString()}]</span>
                    </div>`;
                }
                timeBox.innerHTML = timeStatus;
                verifySignature(); // Auto-verify if key is already there
            } catch (e) {
                headerBox.innerText = "Encoding Conflict: Error decoding Base64 sequence.";
                payloadBox.innerText = "Encoding Conflict.";
            }
        }
        async function verifySignature() {
            const token = document.getElementById('jwt-input').value.trim();
            const secret = document.getElementById('secret-key').value;
            const badge = document.getElementById('sig-status');
            const parts = token.split('.');
            if (parts.length !== 3 || !secret) {
                badge.className = "status-badge bg-slate-100 text-slate-400 border border-slate-200";
                badge.innerText = "Awaiting Secret";
                return;
            }
            // Cryptographic Logic Execution (Web Crypto API)
            try {
                const enc = new TextEncoder();
                const key = await window.crypto.subtle.importKey(
                    "raw",
                    enc.encode(secret),
                    { name: "HMAC", hash: "SHA-256" },
                    false,
                    ["sign"]
                );
                const signature = await window.crypto.subtle.sign(
                    "HMAC",
                    key,
                    enc.encode(parts[0] + "." + parts[1])
                );
                // Convert to Base64Url
                const sigArray = Array.from(new Uint8Array(signature));
                const sigBase64 = btoa(String.fromCharCode.apply(null, sigArray))
                    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
                if (sigBase64 === parts[2]) {
                    badge.className = "status-badge status-valid shadow-emerald-100";
                    badge.innerText = "Signature Verified";
                } else {
                    badge.className = "status-badge status-invalid shadow-rose-100";
                    badge.innerText = "Hash Mismatch";
                }
            } catch (e) {
                console.error(e);
                badge.className = "status-badge status-invalid";
                badge.innerText = "Engine Error";
            }
        }
        function syntaxHighlight(json) {
            if (typeof json != 'string') {
                json = JSON.stringify(json, undefined, 2);
            }
            json = json.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            return json.replace(/("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g, function (match) {
                var cls = 'number';
                if (/^"/.test(match)) {
                    if (/:$/.test(match)) {
                        cls = 'key';
                    } else {
                        cls = 'string';
                    }
                } else if (/true|false/.test(match)) {
                    cls = 'boolean';
                } else if (/null/.test(match)) {
                    cls = 'null';
                }
                return '<span class="' + cls + '">' + match + '</span>';
            });
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
